DROP TABLE IF EXISTS `biz_course`;
CREATE TABLE `biz_course`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `course_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '课程代码',
  `course_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '课程名称',
  `course_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '课程类型：必修/选修/专业核心等',
  `category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '课程分类：编程/设计/产品/数据等',
  `tags` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '课程标签，逗号分隔',
  `credit` decimal(3, 1) NULL DEFAULT NULL COMMENT '学分',
  `period` int NULL DEFAULT NULL COMMENT '学时',
  `semester` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '开课学期',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '课程简介',
  `syllabus` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '课程大纲',
  `teacher` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '授课教师',
  `cover_image` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '课程封面图URL',
  `rating` decimal(2, 1) NULL DEFAULT 5.0 COMMENT '课程评分：1.0-5.0',
  `rating_count` int NULL DEFAULT 0 COMMENT '评分人数',
  `student_count` int NULL DEFAULT 0 COMMENT '学习人数',
  `resource_count` int NULL DEFAULT 0 COMMENT '资源数量',
  `difficulty` tinyint NULL DEFAULT 2 COMMENT '难度：1-初级，2-中级，3-高级',
  `status` tinyint NULL DEFAULT 1 COMMENT '状态：0-停开，1-在开',
  `deleted` tinyint NULL DEFAULT 0 COMMENT '逻辑删除：0-未删除，1-已删除',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_course_code`(`course_code` ASC) USING BTREE,
  INDEX `idx_course_name`(`course_name` ASC) USING BTREE,
  INDEX `idx_course_type`(`course_type` ASC) USING BTREE,
  INDEX `idx_semester`(`semester` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '课程表' ROW_FORMAT = Dynamic;

