DROP TABLE IF EXISTS `biz_course_quiz`;
CREATE TABLE `biz_course_quiz`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `course_id` bigint NOT NULL COMMENT '课程ID',
  `quiz_title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '测验标题',
  `quiz_desc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '测验说明',
  `time_limit` int NULL DEFAULT 60 COMMENT '时限(分钟)',
  `pass_score` int NULL DEFAULT 60 COMMENT '及格分数',
  `max_attempts` int NULL DEFAULT 3 COMMENT '最大尝试次数',
  `total_score` int NULL DEFAULT 100 COMMENT '总分',
  `status` tinyint NULL DEFAULT 1 COMMENT '状态(0-禁用,1-启用)',
