  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '资源描述',
  `sort_order` int NULL DEFAULT 0 COMMENT '排序序号',
  `download_count` int NULL DEFAULT 0 COMMENT '下载次数',
