DROP TABLE IF EXISTS `biz_graduate_registration`;
CREATE TABLE `biz_graduate_registration`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `student_id` bigint NOT NULL COMMENT '学生ID',
  `graduation_year` int NOT NULL COMMENT '毕业年份',
  `graduation_time` date NULL DEFAULT NULL COMMENT '毕业时间',
  `employment_status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '就业状态：EMPLOYED-已就业，FURTHER_STUDY-继续深造，UNEMPLOYED-待业，ENTREPRENEURSHIP-创业',
  `company_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '就业单位',
  `position_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '就业岗位名称',
  `position_category_id` bigint NULL DEFAULT NULL COMMENT '就业岗位分类ID',
  `intended_position_match` tinyint NULL DEFAULT NULL COMMENT '岗位匹配度：0-不匹配，1-部分匹配，2-完全匹配',
  `salary_range` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '薪资范围',
  `work_city` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '工作城市',
  `employment_time` date NULL DEFAULT NULL COMMENT '就业时间',
  `further_study_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '深造类型：MASTER-读研，ABROAD-出国，OTHER-其他',
  `further_study_school` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '深造院校',
  `skill_gap_analysis` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '技能缺口分析（JSON）',
  `course_feedback` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '课程体系反馈',
  `recommendation_rating` tinyint NULL DEFAULT NULL COMMENT '推荐系统评分：1-5分',
  `remarks` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '备注',
  `deleted` tinyint NULL DEFAULT 0 COMMENT '逻辑删除：0-未删除，1-已删除',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_student_year`(`student_id` ASC, `graduation_year` ASC) USING BTREE,
  INDEX `idx_graduation_year`(`graduation_year` ASC) USING BTREE,
  INDEX `idx_employment_status`(`employment_status` ASC) USING BTREE,
  INDEX `idx_position_category`(`position_category_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 21 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '毕业生登记表' ROW_FORMAT = Dynamic;

