  `progress` int NULL DEFAULT 0 COMMENT '观看进度(0-100)',
  `watch_duration` int NULL DEFAULT 0 COMMENT '观看时长(秒)',
  `completed` tinyint NULL DEFAULT 0 COMMENT '是否完成(0-未完成,1-已完成)',
  `last_watch_time` datetime NULL DEFAULT NULL COMMENT '最后观看时间',
  `deleted` tinyint NULL DEFAULT 0 COMMENT '逻辑删除：0-未删除，1-已删除',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_student_resource`(`student_id` ASC, `resource_id` ASC) USING BTREE,
  INDEX `idx_student_course`(`student_id` ASC, `course_id` ASC) USING BTREE,
  INDEX `idx_resource_id`(`resource_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 52 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '学生资源学习进度表' ROW_FORMAT = Dynamic;

