-- ----------------------------
-- Table structure for rel_student_skill_acquired
-- ----------------------------
DROP TABLE IF EXISTS `rel_student_skill_acquired`;
CREATE TABLE `rel_student_skill_acquired`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `student_id` bigint NOT NULL COMMENT '学生ID',
  `skill_id` bigint NOT NULL COMMENT '技能ID',
  `proficiency_level` tinyint NULL DEFAULT 1 COMMENT '掌握程度：1-了解，2-熟练，3-精通',
  `acquire_source` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'COURSE' COMMENT '获取来源：COURSE-课程，SELF-自学，PROJECT-项目，CERTIFICATE-证书',
  `source_id` bigint NULL DEFAULT NULL COMMENT '来源ID（如课程ID）',
  `acquire_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '获取时间',
  `deleted` tinyint NULL DEFAULT 0 COMMENT '逻辑删除：0-未删除，1-已删除',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_student_id`(`student_id` ASC) USING BTREE,
  INDEX `idx_skill_id`(`skill_id` ASC) USING BTREE,
  INDEX `idx_source`(`acquire_source` ASC, `source_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 32 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '学生技能习得表' ROW_FORMAT = Dynamic;

