INSERT INTO `biz_course` VALUES (20, 'T10011', '数据库语言', '专业选修课程', NULL, NULL, 4.0, 48, '2026-2027-2', 'aa', 'bbccdd', '李老师', '/api/uploads/images/course-cover/2026/04/15/e2cb97b8d23a4fa181a2fd57f2651ebb.png', 4.3, 2, 4, 3, 2, 1, 0, '2026-04-08 16:38:16', '2026-04-16 21:12:18');
INSERT INTO `biz_course` VALUES (31, 'KC01004572', '计算机与人工智能导论', '公共基础课', NULL, NULL, 2.0, 32, '2026-2027-2', '本课程面向计算机科学及相关专业学生，旨在系统介绍计算机科学基础与人工智能核心理论。课程以\"理论+实践\"双轨并进的模式推进，前半段聚焦计算机组成、编程基础与算法思维，后半段深入人工智能的数学原理、经典模型与前沿应用。\n\n学生将在每周2学时理论课+2学时实验课的节奏中，完成从\"会用计算机\"到\"理解计算机与AI如何工作\"的认知飞跃。课程末尾设有综合项目，要求学生综合运用所学知识独立完成一个完整的AI小应用。', '计算机组成与工作原理\nCPU、内存、存储、总线；冯·诺依曼体系结构；数制与编码（二进制、ASCII、Unicode）\n操作系统与网络基础\n进程管理、文件系统、内存管理；TCP/IP 协议栈；HTTP 与 Web 基础\n实验：搭建开发环境\nLinux 命令行基础；Git 版本控制入门；Jupyter Notebook 使用', '赵老师', '', 5.0, 0, 0, 0, 2, 1, 0, '2026-04-16 21:11:48', '2026-04-16 21:14:17');
INSERT INTO `biz_course` VALUES (32, 'KC01002373', '计算机组成原理与系统结构', '专业基础课程', NULL, NULL, 2.0, 32, '2026-2027-1', '计算机组成原理与系统结构是一门研究计算机系统内部组成及其工作机制的核心课程，主要讲解从逻辑电路 → CPU → 存储系统 → 指令执行 → 系统结构优化的完整体系，使学生理解程序在硬件上的执行过程，并具备基础的系统级分析与设计能力。', '计算机系统概述\n数据表示与运算\n指令系统（ISA）\nCPU 设计', '刘老师', '', 5.0, 0, 0, 0, 2, 1, 0, '2026-04-16 21:19:31', '2026-04-16 22:01:20');
INSERT INTO `biz_course` VALUES (33, 'KC01000810', '面向对象程序设计Ⅰ', '专业基础课程', NULL, NULL, 3.0, 48, '2026-2027-1', '这门课教你如何用“对象”的方式组织代码，把程序从“函数堆叠”升级为结构清晰、可维护的大型系统。', '1. 面向对象基础\n2. 封装与信息隐藏\n3. 继承与多态\n4. 抽象与接口\n5. 异常处理', '孙老师', '', 5.0, 0, 0, 0, 2, 1, 0, '2026-04-16 21:24:35', '2026-04-16 22:14:00');
INSERT INTO `biz_course` VALUES (34, 'KC01000607', '计算机网络基础', '专业基础课程', NULL, NULL, 2.0, 32, '2026-2027-2', '这门课讲的是：数据是如何从你的电脑传到全世界的，包括协议、传输机制和网络架构。', '1. 网络基础概念\n2. 物理层 & 数据链路层\n3. 网络层\n4. 传输层\n5. 应用层', '周老师', '', 5.0, 0, 0, 0, 2, 1, 0, '2026-04-16 21:27:28', '2026-04-16 21:59:46');
INSERT INTO `biz_course` VALUES (35, 'KC01000514', '软件工程', '专业核心课程', NULL, NULL, 2.0, 32, '2026-2027-2', '该课程将教会你如何把一个软件从0做到上线，包括需求、设计、开发、测试、维护的全过程，软件过程是“做项目的方法论”。', '1. 软件工程概述\n2. 需求分析\n3. 系统设计\n4. 软件实现\n5. 软件测试', '王老师', '', 5.0, 0, 0, 0, 2, 1, 0, '2026-04-16 22:06:51', '2026-04-16 22:06:51');
INSERT INTO `biz_course` VALUES (36, 'KC01002367', '软件测试与质量保证', '专业核心课程', NULL, NULL, 2.0, 32, '2027-2028-1', '这门课关注的是：如何系统地发现问题，并保证软件质量，不仅是“找bug”，更是“防bug”。', '1. 软件质量基础\n2. 测试基础\n3. 黑盒测试\n4. 白盒测试\n5. 测试管理\n6. 质量保证体系', '黄老师', '', 5.0, 0, 0, 0, 2, 1, 0, '2026-04-16 22:10:07', '2026-04-16 22:10:19');
