INSERT INTO `biz_quiz_question` VALUES (13, 4, 'Java中main方法的正确声明是？', 'single_choice', '[\"A. public void main(String[] args)\",\"B. public static void main(String[] args)\",\"C. static void main(String args[])\",\"D. public static main(String[] args)\"]', 'B', 20, 1, 'main方法必须是public static void，参数为String数组', 0, '2026-03-31 12:05:00', '2026-03-31 12:05:00');
INSERT INTO `biz_quiz_question` VALUES (14, 4, '以下哪个是Java的基本数据类型？', 'single_choice', '[\"A. String\",\"B. Integer\",\"C. int\",\"D. ArrayList\"]', 'C', 20, 2, 'int是基本数据类型，其他都是引用类型', 0, '2026-03-31 12:06:00', '2026-03-31 12:06:00');
INSERT INTO `biz_quiz_question` VALUES (15, 4, 'Java中用于定义常量的关键字是？', 'single_choice', '[\"A. static\",\"B. final\",\"C. const\",\"D. constant\"]', 'B', 20, 3, 'final关键字用于定义常量', 0, '2026-03-31 12:07:00', '2026-03-31 12:07:00');
INSERT INTO `biz_quiz_question` VALUES (16, 4, '以下哪些是Java的访问修饰符？', 'multi_choice', '[\"A. public\",\"B. private\",\"C. protected\",\"D. static\"]', 'A,B,C', 20, 4, 'public、private、protected是访问修饰符，static不是', 0, '2026-03-31 12:08:00', '2026-03-31 12:08:00');
