INSERT INTO `biz_quiz_question` VALUES (19, 5, '以下关于构造方法的说法正确的是？', 'single_choice', '[\"A. 构造方法可以有返回值\",\"B. 构造方法必须与类名相同\",\"C. 一个类只能有一个构造方法\",\"D. 构造方法不能被重载\"]', 'B', 20, 2, '构造方法必须与类名相同，无返回值，可以重载', 0, '2026-03-31 12:36:00', '2026-03-31 12:36:00');
INSERT INTO `biz_quiz_question` VALUES (20, 5, '以下哪些是Java中的引用类型？', 'multi_choice', '[\"A. int\",\"B. String\",\"C. Object\",\"D. double\"]', 'B,C', 20, 3, 'String和Object是引用类型，int和double是基本类型', 0, '2026-03-31 12:37:00', '2026-03-31 12:37:00');
INSERT INTO `biz_quiz_question` VALUES (21, 5, '子类可以继承父类的私有成员。', 'judge', NULL, 'false', 20, 4, '子类不能继承父类的私有(private)成员', 0, '2026-03-31 12:38:00', '2026-03-31 12:38:00');
