INSERT INTO `biz_quiz_question` VALUES (23, 6, 'HTML中用于定义最大标题的标签是？', 'single_choice', '[\"A. <head>\",\"B. <header>\",\"C. <h1>\",\"D. <title>\"]', 'C', 25, 1, 'h1是最大标题标签', 0, '2026-04-08 11:32:00', '2026-04-08 11:32:00');
