INSERT INTO `biz_quiz_question` VALUES (31, 8, 'Linux中查看当前目录的命令是？', 'single_choice', '[\"A. ls\",\"B. pwd\",\"C. cd\",\"D. dir\"]', 'B', 25, 1, 'pwd显示当前工作目录', 0, '2026-04-08 11:32:00', '2026-04-08 11:32:00');
INSERT INTO `biz_quiz_question` VALUES (32, 8, 'Linux中创建目录的命令是？', 'single_choice', '[\"A. create\",\"B. mkdir\",\"C. newdir\",\"D. makedir\"]', 'B', 25, 2, 'mkdir用于创建目录', 0, '2026-04-08 11:33:00', '2026-04-08 11:33:00');
INSERT INTO `biz_quiz_question` VALUES (33, 8, 'Linux中root用户拥有最高权限。', 'judge', NULL, 'true', 25, 3, 'root是超级用户，拥有系统最高权限', 0, '2026-04-08 11:34:00', '2026-04-08 11:34:00');
INSERT INTO `biz_quiz_question` VALUES (34, 8, 'rm -rf / 是安全的命令。', 'judge', NULL, 'false', 25, 4, '该命令会强制删除根目录下所有文件，极其危险', 0, '2026-04-08 11:35:00', '2026-04-08 11:35:00');
INSERT INTO `biz_quiz_question` VALUES (35, 9, 'SQL中用于查询数据的关键字是？', 'single_choice', '[\"A. FIND\",\"B. QUERY\",\"C. SELECT\",\"D. GET\"]', 'C', 25, 1, 'SELECT用于查询数据', 0, '2026-04-08 17:05:00', '2026-04-08 17:05:00');
INSERT INTO `biz_quiz_question` VALUES (36, 9, 'SQL中用于插入数据的关键字是？', 'single_choice', '[\"A. ADD\",\"B. INSERT\",\"C. CREATE\",\"D. PUT\"]', 'B', 25, 2, 'INSERT INTO用于插入数据', 0, '2026-04-08 17:06:00', '2026-04-08 17:06:00');
INSERT INTO `biz_quiz_question` VALUES (37, 9, 'SQL语句必须以分号结尾。', 'judge', NULL, 'false', 25, 3, 'SQL语句不是必须以分号结尾，但建议使用', 0, '2026-04-08 17:07:00', '2026-04-08 17:07:00');
INSERT INTO `biz_quiz_question` VALUES (38, 9, 'SELECT * 会返回所有列。', 'judge', NULL, 'true', 25, 4, '*表示所有列', 0, '2026-04-08 17:08:00', '2026-04-08 17:08:00');
INSERT INTO `biz_quiz_question` VALUES (39, 10, '数据库第一范式要求？', 'single_choice', '[\"A. 每个表必须有主键\",\"B. 每个字段必须原子性\",\"C. 消除传递依赖\",\"D. 消除部分依赖\"]', 'B', 25, 1, '第一范式要求字段原子性，不可再分', 0, '2026-04-08 17:35:00', '2026-04-08 17:35:00');
INSERT INTO `biz_quiz_question` VALUES (40, 10, '数据库第三范式要求消除？', 'single_choice', '[\"A. 完全依赖\",\"B. 部分依赖\",\"C. 传递依赖\",\"D. 多值依赖\"]', 'C', 25, 2, '第三范式要求消除传递依赖', 0, '2026-04-08 17:36:00', '2026-04-08 17:36:00');
INSERT INTO `biz_quiz_question` VALUES (41, 10, '外键用于建立表之间的关联。', 'judge', NULL, 'true', 25, 3, '外键用于建立表间关系', 0, '2026-04-08 17:37:00', '2026-04-08 17:37:00');
INSERT INTO `biz_quiz_question` VALUES (42, 10, '数据库设计时应该尽量使用冗余数据。', 'judge', NULL, 'false', 25, 4, '应尽量减少冗余，遵循规范化原则', 0, '2026-04-08 17:38:00', '2026-04-08 17:38:00');
